INSERT INTO public."Tour" VALUES ('cmi7v7qrj001f779xymugxx46', 'parque-trekking-canoas', 'PARQUE TREKKING & CANOAS', 'Naturaleza', 'summer', 'Media', 8, '/images/tours/parque-trekking-canoas/featured.jpg', '/images/tours/parque-trekking-canoas/hero.jpg', 'Una experiencia para disfrutar en el Parque Nacional Tierra del Fuego, combinando trekking costero y canoas en el Canal Beagle.', 'Salida desde el hotel en minibús rumbo al Parque Nacional Tierra del Fuego, más precisamente a Ensenada Zaratiegui, donde podremos disfrutar de hermosas vistas del Canal Beagle, con las islas Redonda, Hoste y Navarino como protagonistas.
INSERT INTO public."Tour" VALUES ('cmi7v7qsc002x779xaknkyl88', 'trekking-glaciar-vinciguerra', 'TREKKING GLACIAR VINCIGUERRA', 'Aventura Extrema', 'summer', 'Alta', 8, '/images/tours/trekking-glaciar-vinciguerra/featured.jpg', '/images/tours/trekking-glaciar-vinciguerra/hero.jpg', 'Un trekking exigente hacia la Laguna de los Témpanos y el Glaciar Vinciguerra, ideal para grandes aventureros.', 'Comenzamos la caminata en el valle de Andorra, donde después de cruzar antiquísimas turberas nos adentramos en el bosque fueguino. A medida que ganamos altura, el paisaje va cambiando hasta llegar a orillas de la Laguna de los Témpanos, con imponentes vistas del Glaciar Vinciguerra.
INSERT INTO public."Tour" VALUES ('cmi7v7qr1000o779x7ojiybld', 'lagos-off-road', 'LAGOS OFF ROAD', 'Aventura 4x4', 'summer', 'Media', 7, '/images/tours/lagos-off-road/featured.jpg', '/images/tours/lagos-off-road/hero.jpg', 'Aventura y paisajes únicos', 'Salida desde el hotel por la mañana rumbo a los Lagos por la ruta 3 que recorre parte de la cordillera fueguina y nos permite acceder al paso Garibaldi, punto panorámico desde donde podemos ver nuestros objetivos, los lagos Escondido y Fagnano. Comenzamos el descenso y nos desviamos de la ruta por antiguas huellas de leñadores. Las camionetas 4x4 nos permiten llegar a lugares donde el acceso sería imposible de otra manera, bosques, barro, piedras, etc… El lago Fagnano nos sorprende con sus dimensiones y su increíble paisaje.
INSERT INTO public."Tour" VALUES ('cmi7v7qsz0044779xkpty0z58', 'pinguinera-isla-martillo', 'PINGUINERA ISLA MARTILLO', 'Fauna', 'summer', 'Baja', 6, '/images/tours/pinguinera-isla-martillo/featured.jpg', '/images/tours/pinguinera-isla-martillo/hero.jpg', 'Navegación por el Canal Beagle hacia Isla Martillo para avistar pingüinos magallánicos y fauna marina del fin del mundo.', 'Embarcamos en el muelle de Ushuaia para navegar por el Canal Beagle hacia Isla de los Pájaros, Isla de los Lobos y el icónico Faro Les Eclaireurs, disfrutando de las mejores vistas panorámicas de la ciudad y las montañas que la rodean.
INSERT INTO public."Tour" VALUES ('cmi7v7qtg005i779x9we5pf9f', 'parque-nacional-clasico-winter', 'PARQUE NACIONAL CLÁSICO', 'El Parque del fin del mundo!!', 'winter', 'Baja', 4, '/images/tours/parque-nacional-clasico/featured.jpg', '/images/tours/parque-nacional-clasico/featured.jpg', 'El Parque del fin del mundo!!', '', '', true, '2025-11-20 20:09:44.836', '2025-11-20 20:09:44.836', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public."Tour" VALUES ('cmi7v7qtj005m779xfrxge096', 'canal-beagle-catamaran', 'CANAL BEAGLE EN CATAMARAN', 'Navegación', 'summer', 'Baja', 3, '/images/tours/canal-beagle-catamaran/featured.jpg', '/images/tours/canal-beagle-catamaran/hero.jpg', 'Navegación en catamarán por el Canal Beagle con vistas panorámicas de Ushuaia, fauna marina y el emblemático faro Les Eclaireurs.', 'La excursión comienza en el puerto de Ushuaia, en pleno centro de la ciudad. Navegaremos primero por la Bahía Ushuaia, desde donde se obtiene una vista panorámica de la ciudad, las montañas y los valles. Se destacan el edificio del antiguo presidio (hoy Museo Marítimo), el Museo del Fin del Mundo, el sector industrial y los montes Olivia y Cinco Hermanos.
INSERT INTO public."Tour" VALUES ('cmi7v7qtp0069779xw68ti60v', 'canal-beagle-catamaran-winter', 'CANAL BEAGLE EN CATAMARAN', 'Navegación', 'winter', 'Baja', 4, '/images/tours/canal-beagle-catamaran/featured.jpg', '/images/tours/canal-beagle-catamaran/featured.jpg', 'Navegación', '', '', true, '2025-11-20 20:09:44.846', '2025-11-20 20:09:44.846', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public."Tour" VALUES ('cmi7v7qts006d779xmyi5pbzs', 'full-day-nieve', 'FULL DAY NIEVE', 'Aventura en la Nieve', 'winter', 'Baja', 8, '/images/tours/full-day-nieve/featured.jpg', '/images/tours/full-day-nieve/hero.jpg', 'La opción más completa para disfrutar la nieve fueguina.', 'Partimos desde tu alojamiento rumbo al valle Tierra Mayor, donde comienza la aventura en el Husky Park. Luego de la bienvenida de los guías, te equipás con raquetas de nieve para recorrer el valle y el bosque fueguino, accediendo a increíbles puntos panorámicos de la cordillera.
INSERT INTO public."Tour" VALUES ('cmi7v7qt8004v779x2e4zdlnj', 'parque-nacional-clasico', 'PARQUE NACIONAL CLÁSICO', 'El Parque del fin del mundo!!', 'summer', 'Baja', 6, '/images/tours/parque-nacional-clasico/featured.jpg', '/images/tours/parque-nacional-clasico/hero.jpg', 'El Parque Nacional del Fin del Mundo, único en Argentina por albergar montañas, mar y bosque a pocos kilómetros de Ushuaia.', 'El Parque Nacional Tierra del Fuego se encuentra ubicado a solo 12 kilómetros de la ciudad de Ushuaia. Es único en Argentina por albergar montañas, mar y bosque en un mismo entorno. La excursión comienza recorriendo parte de la Ruta Nacional N°3, atravesando el valle del río Pipo y el faldeo del Monte Susana hasta llegar a la estación del Ferrocarril Austral Fueguino, uno de los sectores donde trabajaban los reclusos del antiguo presidio de Ushuaia.
INSERT INTO public."Tour" VALUES ('cmi7v7qu40082779x7zrqdv7k', 'nieve-fuego', 'NIEVE & FUEGO', 'Aventura Nocturna', 'winter', 'Baja', 5, '/images/tours/nieve-fuego/featured.jpg', '/images/tours/nieve-fuego/hero.jpg', 'Aventura nocturna en la nieve con trineo Husky, moto de nieve, raquetas y cena en fogón.', 'Comenzamos al atardecer con el traslado desde tu alojamiento hacia Husky Park, en el valle Tierra Mayor. Al llegar, el guía da la bienvenida en el Domo La Base y explica cómo será la experiencia nocturna en la nieve.
INSERT INTO public."Tour" VALUES ('cmi7v7qub0090779xnh2b7cwg', '4x4-invernal', '4X4 INVERNAL', 'Aventura 4x4', 'winter', 'Baja', 8, '/images/tours/4x4-invernal/featured.jpg', '/images/tours/4x4-invernal/hero.jpg', 'Una travesía todo terreno para descubrir los lagos Escondido y Fagnano en 4x4.', 'Partida desde el hotel por la ruta nacional N° 3 rumbo a los lagos Escondido y Fagnano. En el camino cruzamos la cordillera fueguina por el Paso Garibaldi, con vistas panorámicas únicas.
INSERT INTO public."Tour" VALUES ('cmi7v7qui009n779xd6gp30uu', 'trekking-esmeralda-invernal', 'TREKKING ESMERALDA INVERNAL', 'Trekking Invernal', 'winter', 'Media', 7, '/images/tours/trekking-esmeralda-invernal/featured.jpg', '/images/tours/trekking-esmeralda-invernal/hero.jpg', 'Un trekking invernal único hacia la Laguna Esmeralda, atravesando valles, bosques y arroyos congelados.', 'Partida desde el hotel en minibús por vía terrestre (20 km) hasta el valle Tierra Mayor. Desde el refugio Nunatak y luego de equiparnos con crampones o raquetas de nieve iniciamos la caminata, atravesando grandes valles cubiertos de nieve, arroyos congelados y centenarios bosques de lengas y coihues.
INSERT INTO public."Tour" VALUES ('cmi7v7qun00a8779xdxem53dt', 'aventura-blanca', 'AVENTURA BLANCA', 'Trineos con Perros', 'winter', 'Baja', 5, '/images/tours/aventura-blanca/featured.jpg', '/images/tours/aventura-blanca/hero.jpg', 'Aventura en trineo Husky y motos de nieve, con visita al parque y chocolate caliente en el valle Tierra Mayor.', 'Partida desde tu hotel con destino al valle Tierra Mayor, donde se encuentra Husky Park Ushuaia. Al llegar, realizamos una visita guiada por el parque para conocer la historia, el cuidado y el entrenamiento de los perros de trineo, y la muestra dedicada a los exploradores de la nieve.
INSERT INTO public."Tour" VALUES ('cmi7v7qut00ay779xdbrgrq44', 'experiencia-antartica', 'EXPERIENCIA ANTÁRTICA', 'Aventura Antártica', 'winter', 'Baja', 5, '/images/tours/experiencia-antartica/featured.jpg', '/images/tours/experiencia-antartica/hero.jpg', 'Desafío polar con vehículos a oruga, motos de nieve y experiencia inmersiva en un módulo antártico.', 'La experiencia comienza con el traslado desde tu hotel en nuestros exclusivos transfers hacia Husky Park Ushuaia, en el valle Tierra Mayor. Allí, al pie del monumento a los exploradores, el guía introduce el mundo de la exploración antártica y las heroicas travesías en el continente blanco.
INSERT INTO public."Tour" VALUES ('cmi7v7qrz0028779xgxp0iyhm', 'parque-aventura', 'PARQUE AVENTURA', 'Un parque a tu medida!!', 'summer', 'Media', 5, '/images/tours/parque-aventura/featured.jpg', '/images/tours/parque-aventura/hero.jpg', 'Una experiencia para disfrutar en el Parque Nacional Tierra del Fuego, con pequeñas caminatas, vistas increíbles y almuerzo a orillas del río Lapataia.', 'Salida desde el hotel en minibús rumbo al Parque Nacional Tierra del Fuego, la primer parada será en Ensenada Zaratiegui, donde podremos disfrutar de hermosas vistas del Canal Beagle, con las islas Redonda, Hoste y Navarino como protagonistas. La próxima parada nos acerca al lago Roca, bellísimo lago compartido con Chile, finalmente llegamos a la bahía Lapataia en el Canal Beagle, precisamente donde culmina la Ruta Panamericana y Ruta Nacional Nº 3.
INSERT INTO public."Tour" VALUES ('cmi7v7qso003j779xyimkkh7z', 'trekking-laguna-esmeralda', 'TREKKING LAGUNA ESMERALDA', 'Naturaleza', 'summer', 'Media', 7, '/images/tours/trekking-laguna-esmeralda/featured.jpg', '/images/tours/trekking-laguna-esmeralda/hero.jpg', 'Una caminata sin igual hasta la Laguna Esmeralda, atravesando turberas, arroyos y bosques fueguinos.', 'Partida desde el hotel en minibús por vía terrestre (20 kms) hasta el valle Tierra Mayor. Desde el refugio Nunatak iniciamos la caminata durante la cual atravesamos túrbales, arroyos y centenarios bosques de Lengas y Coihues. La posibilidad de avistar zorros, cóndores y castores está siempre latente.
INSERT INTO public."Tour" VALUES ('cmi7v7qty007d779xtfylma6z', 'experiencia-husky', 'EXPERIENCIA HUSKY', 'Trineos con Perros', 'winter', 'Media', 6, '/images/tours/experiencia-husky/featured.jpg', '/images/tours/experiencia-husky/hero.jpg', 'Viví la experiencia de conducir tu propio trineo de perros en el valle Tierra Mayor, rodeado de nieve y silencio blanco.', 'Partida desde el hotel rumbo al valle Tierra Mayor, donde comienza la aventura. Nuestro Musher instructor nos da la bienvenida brindándonos una charla introductoria al mundo de los perros de trineo y visitando el criadero/parque Husky.
INSERT INTO public."Tour" VALUES ('cmicbcz2v00009gr81gigy525', 'caminata-husky', 'CAMINATA HUSKY', 'Caminata con huskies en Tierra Mayor', 'summer', 'Baja', 5, '/images/tours/caminata-husky/featured.jpg', '/images/tours/caminata-husky/hero.jpg', 'Caminata de 2 km con huskies en el Husky Park Ushuaia, ubicado en el corazón de la Reserva Natural y Paisajística Tierra Mayor. Incluye visita guiada, caminata con los perros y almuerzo en restaurante Tierra Mayor.', 'Disfrutá de una experiencia original con amigables huskies.
