INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qt6004t779xzolurb9t', 'cmi7v7qsz0044779xkpty0z58', 'check', 'Incluye tasa de puerto', 'La tarifa indicada incluye la tasa de puerto para el embarque en Ushuaia.', 1, '2025-11-20 20:09:44.826', '2025-11-20 20:09:44.826');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qtd005f779xptfmpdfb', 'cmi7v7qt8004v779x2e4zdlnj', 'family', 'Apto para familias', 'Excursión de baja dificultad, ideal para todas las edades, con traslados en bus y pequeñas caminatas.', 0, '2025-11-20 20:09:44.834', '2025-11-20 20:09:44.834');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qtd005g779xqndwu8th', 'cmi7v7qt8004v779x2e4zdlnj', 'book-a', 'Guía en Inglés y Español', 'Guías especializados y bilingües que acompañan durante todo el recorrido por el Parque Nacional.', 1, '2025-11-20 20:09:44.834', '2025-11-20 20:09:44.834');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qtn0066779xqk8x024n', 'cmi7v7qtj005m779xfrxge096', 'book-a', 'Guía en Inglés y Español', 'Guías bilingües especializados acompañan durante toda la navegación por el Canal Beagle.', 0, '2025-11-20 20:09:44.844', '2025-11-20 20:09:44.844');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qtn0067779x0zihcflu', 'cmi7v7qtj005m779xfrxge096', 'binoculars', 'Fauna y paisajes únicos', 'Avistaje de lobos marinos, cormoranes, aves marinas y vistas panorámicas de Ushuaia y la cordillera fueguina.', 1, '2025-11-20 20:09:44.844', '2025-11-20 20:09:44.844');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qtw007a779xgaqr7j8g', 'cmi7v7qts006d779xmyi5pbzs', 'family', 'Apto para familias', 'Pasajeros de todas las edades podrán disfrutar de este paseo y sus actividades en la nieve.', 0, '2025-11-20 20:09:44.853', '2025-11-20 20:09:44.853');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qtw007b779x2nnxnr01', 'cmi7v7qts006d779xmyi5pbzs', 'book-a', 'Guía en Inglés y Español', 'Contamos con guías bilingües especializados para acompañarte durante toda la experiencia.', 1, '2025-11-20 20:09:44.853', '2025-11-20 20:09:44.853');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qu2007y779xytku0hc8', 'cmi7v7qty007d779xtfylma6z', 'family', 'Apto para familias', 'Ideal para quienes buscan una experiencia diferente en la nieve, compartida entre grandes y chicos.', 0, '2025-11-20 20:09:44.859', '2025-11-20 20:09:44.859');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qu2007z779xj0x3pswo', 'cmi7v7qty007d779xtfylma6z', 'alert-circle', 'Requiere buen estado físico', 'Actividad comparable al esquí de fondo. Recomendado para pasajeros con razonable forma física y sin problemas de salud.', 1, '2025-11-20 20:09:44.859', '2025-11-20 20:09:44.859');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qu20080779x9pb6glgb', 'cmi7v7qty007d779xtfylma6z', 'book-a', 'Guía en Inglés y Español', 'Guías especializados y bilingües acompañan y asisten durante toda la experiencia con los huskies.', 2, '2025-11-20 20:09:44.859', '2025-11-20 20:09:44.859');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qu9008w779xncaz43ci', 'cmi7v7qu40082779x7zrqdv7k', 'family', 'Apto para familias', 'Pasajeros de diferentes edades pueden disfrutar de las actividades nocturnas en la nieve.', 0, '2025-11-20 20:09:44.865', '2025-11-20 20:09:44.865');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qu9008x779xufnazd4a', 'cmi7v7qu40082779x7zrqdv7k', 'clock', 'Experiencia nocturna', 'Viví la nieve bajo las estrellas, combinando aventura y una cena cálida en fogón.', 1, '2025-11-20 20:09:44.865', '2025-11-20 20:09:44.865');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qu9008y779xr66wngtd', 'cmi7v7qu40082779x7zrqdv7k', 'book-a', 'Guías especializados', 'Guías con experiencia en actividades invernales te acompañan durante todo el recorrido.', 2, '2025-11-20 20:09:44.865', '2025-11-20 20:09:44.865');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7quf009k779xaraczg5n', 'cmi7v7qub0090779xnh2b7cwg', 'alert-circle', 'No apto para embarazadas', 'Excursión no recomendada para personas con problemas de columna, dolencias físicas importantes o mujeres embarazadas.', 0, '2025-11-20 20:09:44.872', '2025-11-20 20:09:44.872');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7quf009l779xs8wigwus', 'cmi7v7qub0090779xnh2b7cwg', 'book-a', 'Guía en Inglés y Español', 'Contamos con guías bilingües especializados para acompañarte durante toda la travesía.', 1, '2025-11-20 20:09:44.872', '2025-11-20 20:09:44.872');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qul00a5779xonogg5zi', 'cmi7v7qui009n779xd6gp30uu', 'check', 'Equipo incluido', 'Proveemos crampones o raquetas de nieve, bastón de trekking y box lunch (sándwich, alfajor, barrita de cereal y agua).', 0, '2025-11-20 20:09:44.878', '2025-11-20 20:09:44.878');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qul00a6779xa53nqibz', 'cmi7v7qui009n779xd6gp30uu', 'alert-circle', 'Requiere buen estado físico', 'Terreno con desniveles, sectores inclinados, barro, piedras, nieve y hielo. No apto para embarazadas ni personas con problemas cardíacos, respiratorios, circulatorios o de columna.', 1, '2025-11-20 20:09:44.878', '2025-11-20 20:09:44.878');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qur00av779x666sfl2x', 'cmi7v7qun00a8779xdxem53dt', 'family', 'Apto para familias', 'Pasajeros de distintas edades podrán disfrutar de este paseo y todas sus actividades en la nieve.', 0, '2025-11-20 20:09:44.884', '2025-11-20 20:09:44.884');
INSERT INTO public."TourFeaturedInfo" VALUES ('cmi7v7qur00aw779xztwmo42i', 'cmi7v7qun00a8779xdxem53dt', 'book-a', 'Guía en Inglés y Español', 'Guías bilingües especializados acompañan la visita al parque y las actividades en trineo y motos de nieve.', 1, '2025-11-20 20:09:44.884', '2025-11-20 20:09:44.884');
