INSERT INTO public."TourTestimonial" VALUES ('cmi7v7qrg001e779xzd8kglfn', 'cmi7v7qr1000o779x7ojiybld', 'Inesquecível passeio 4x4. O profesional Cristian conduziu um dia inteiro entre trilha, canoagem, explicações da fauna e flora e un excelente almuerzo en la cabana. Super-recomendo.', 'Adriana S. Magalhães', '/images/testimonials/author-1.jpg', 'Brasil', 0, '2025-11-20 20:09:44.765', '2025-11-20 20:09:44.765');
INSERT INTO public."TourTestimonial" VALUES ('cmi7v7qrw0027779xhzxsm2xq', 'cmi7v7qrj001f779xymugxx46', 'Inesquecível passeio 4x4. O profissional Cristian conduziu um dia inteiro entre trilha, canoagem, explicações da fauna e flora e um excelente almoço na cabana. Super-recomendo.', 'Adriana S. Magalhães', '/images/testimonials/author-1.jpg', 'Brasil', 0, '2025-11-20 20:09:44.781', '2025-11-20 20:09:44.781');
INSERT INTO public."TourTestimonial" VALUES ('cmi7v7qsa002w779x8rul5i6b', 'cmi7v7qrz0028779xgxp0iyhm', 'Inesquecível passeio 4x4. O profissional Cristian conduziu um dia inteiro entre trilha, canoagem, explicações da fauna e flora e um excelente almoço na cabana. Super-recomendo.', 'Adriana S. Magalhães', '/images/testimonials/author-1.jpg', 'Brasil', 0, '2025-11-20 20:09:44.794', '2025-11-20 20:09:44.794');
INSERT INTO public."TourTestimonial" VALUES ('cmi7v7qsm003i779xm69e13p0', 'cmi7v7qsc002x779xaknkyl88', 'Hice el trekking al Glaciar Vinciguerra y la Laguna de los Témpanos. El esfuerzo vale totalmente la pena: paisajes increíbles y una experiencia inolvidable.', 'Vanesa P.', '/images/testimonials/author-1.jpg', 'Argentina', 0, '2025-11-20 20:09:44.806', '2025-11-20 20:09:44.806');
INSERT INTO public."TourTestimonial" VALUES ('cmi7v7qsx0043779x7gg4ug23', 'cmi7v7qso003j779xyimkkh7z', 'Inesquecível passeio 4x4. O profissional Cristian conduziu um dia inteiro entre trilha, canoagem, explicações da fauna e flora e um excelente almoço na cabana. Super-recomendo.', 'Adriana S. Magalhães', '/images/testimonials/author-1.jpg', 'Brasil', 0, '2025-11-20 20:09:44.818', '2025-11-20 20:09:44.818');
INSERT INTO public."TourTestimonial" VALUES ('cmi7v7qt6004u779xudu5voml', 'cmi7v7qsz0044779xkpty0z58', 'Inesquecível passeio! A navegação até a Pinguinera Isla Martillo foi maravilhosa, vimos muitos pingüins e a paisagem do Canal Beagle é inesquecível.', 'Adriana S. Magalhães', '/images/testimonials/author-1.jpg', 'Brasil', 0, '2025-11-20 20:09:44.827', '2025-11-20 20:09:44.827');
INSERT INTO public."TourTestimonial" VALUES ('cmi7v7qte005h779x4wns38s4', 'cmi7v7qt8004v779x2e4zdlnj', 'El Parque Nacional Tierra del Fuego es increíble. La combinación de bosque, montaña y mar en un solo paseo es única. La organización de la excursión fue excelente.', 'María L.', '/images/testimonials/author-1.jpg', 'Argentina', 0, '2025-11-20 20:09:44.835', '2025-11-20 20:09:44.835');
INSERT INTO public."TourTestimonial" VALUES ('cmi7v7qto0068779xmmgds9jg', 'cmi7v7qtj005m779xfrxge096', 'Hermosa navegación por el Canal Beagle. Vimos lobos marinos, muchas aves y el faro Les Eclaireurs de cerca. Súper recomendable para conocer Ushuaia desde el mar.', 'Carolina M.', '/images/testimonials/canal-beagle-catamaran-1.jpg', 'Argentina', 0, '2025-11-20 20:09:44.844', '2025-11-20 20:09:44.844');
INSERT INTO public."TourTestimonial" VALUES ('cmi7v7qtx007c779ximfuuwsc', 'cmi7v7qts006d779xmyi5pbzs', 'Inesquecível passeio 4x4. O profissional Cristian conduziu um dia inteiro entre trilha, canoagem, explicações da fauna e flora e um excelente almoço na cabana. Super-recomendo.', 'Adriana S. Magalhães', '/images/testimonials/author-1.jpg', 'Brasil', 0, '2025-11-20 20:09:44.853', '2025-11-20 20:09:44.853');
INSERT INTO public."TourTestimonial" VALUES ('cmi7v7qu30081779x0hybbz0b', 'cmi7v7qty007d779xtfylma6z', 'Mi primer excursión con Antartur fue increíble, excelentes profesionales tienen como guías, te explican, aclaran y comparten experiencias únicas que hacen de cada lugar totalmente único. Muchas gracias.', 'Yesica Pare', '/images/testimonials/experiencia-husky-1.jpg', 'Argentina', 0, '2025-11-20 20:09:44.86', '2025-11-20 20:09:44.86');
INSERT INTO public."TourTestimonial" VALUES ('cmi7v7qua008z779xoyauj12u', 'cmi7v7qu40082779x7zrqdv7k', 'Excelente experiencia al llegar a Ushuaia, muy interactiva, cordial y una velada perfecta en la nieve.', 'Marcela M', '/images/testimonials/nieve-fuego-1.jpg', 'Argentina', 0, '2025-11-20 20:09:44.866', '2025-11-20 20:09:44.866');
INSERT INTO public."TourTestimonial" VALUES ('cmi7v7qug009m779x8n52dr5j', 'cmi7v7qub0090779xnh2b7cwg', 'Hice con mi mujer la excursión 4x4 por el bosque andino patagónico y nos encantó. Además, nuestro guía, Azariel, fue muy amable, agradable y dinámico, explicó todo con mucho detalle y de manera muy interesante. Por último, cocinó un asado estupendo. Repetiríamos seguro. ¡Top!', 'Ángel Olavarría Bernal', '/images/testimonials/4x4-invernal-1.jpg', 'Argentina', 0, '2025-11-20 20:09:44.873', '2025-11-20 20:09:44.873');
INSERT INTO public."TourTestimonial" VALUES ('cmi7v7qum00a7779xv9pt93md', 'cmi7v7qui009n779xd6gp30uu', 'Hermosa experiencia de trekking invernal. El paisaje de Laguna Esmeralda congelada es impresionante y los guías de Antartur acompañan en todo momento.', 'Lucía P.', '/images/testimonials/trekking-esmeralda-invernal-1.jpg', 'Argentina', 0, '2025-11-20 20:09:44.878', '2025-11-20 20:09:44.878');
INSERT INTO public."TourTestimonial" VALUES ('cmi7v7qus00ax779xp15z1axs', 'cmi7v7qun00a8779xdxem53dt', 'Una excursión hermosa para hacer en familia. Los chicos disfrutaron muchísimo del paseo en trineo y de los huskies, y el recorrido en moto de nieve fue increíble.', 'Carolina R.', '/images/testimonials/aventura-blanca-1.jpg', 'Argentina', 0, '2025-11-20 20:09:44.884', '2025-11-20 20:09:44.884');
INSERT INTO public."TourTestimonial" VALUES ('cmi7v7quy00bn779xxm2u5k7f', 'cmi7v7qut00ay779xdbrgrq44', 'Una experiencia distinta a todo lo que habíamos hecho en Ushuaia. La travesía en vehículos a oruga y la experiencia inmersiva en el módulo antártico son imperdibles.', 'Gustavo J', '/images/testimonials/experiencia-antartica-1.jpg', 'Argentina', 0, '2025-11-20 20:09:44.891', '2025-11-20 20:09:44.891');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qra0015779xamhyz9no', 'cmi7v7qr1000o779x7ojiybld', '9:00 AM', 'Salimos desde tu hotel', 'Salida desde el hotel por la mañana rumbo a los Lagos, tomamos la ruta nacional N°3 que recorre parte de la cordillera fueguina.', 0, '2025-11-20 20:09:44.759', '2025-11-20 20:09:44.759');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qra0016779xlhdsfew6', 'cmi7v7qr1000o779x7ojiybld', '9:45 AM', 'Cruce Andes Fueguinos', 'Accedemos al paso garibaldi, punto más alto de la ruta 3 con inmejorable vistas de los lagos Escondido y Fagnano', 1, '2025-11-20 20:09:44.759', '2025-11-20 20:09:44.759');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qra0017779x9xj85rig', 'cmi7v7qr1000o779x7ojiybld', '10:15', 'Canotaje en lago Escondido', 'Luego de una charla introductoria de nuestros guías boteros, preparamos las canoas, y a remar. La vista desde el agua nos sorprende.', 2, '2025-11-20 20:09:44.759', '2025-11-20 20:09:44.759');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qra0018779x1jpqce3q', 'cmi7v7qr1000o779x7ojiybld', '11:15', 'Ruta 119 - Hacia el Lago Fuera de Ruta', 'Nos desviamos por la ruta Provincial 119, que nos permitira acceder a antiguas huellas de leñadores. Las camionetas 4×4 nos permiten llegar a lugares donde el acceso sería imposible de otra manera, bosques, barro, piedras, la aventura continua…', 3, '2025-11-20 20:09:44.759', '2025-11-20 20:09:44.759');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qra0019779xp50ruqxq', 'cmi7v7qr1000o779x7ojiybld', '12:15 PM', 'Lago Fagnano', 'y llegamos al lago, nos sorprenden sus dimensiones, parada obligada ante semejante paisaje.. luego continuamos orillando el lago hasta acceder nuevamente a la ruta 3 y regreso al valle Tierra Mayor.', 4, '2025-11-20 20:09:44.759', '2025-11-20 20:09:44.759');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qra001a779xkdfw1nxj', 'cmi7v7qr1000o779x7ojiybld', '14:00 PM', 'Almuerzo en Nunatak', 'El Refugio Nunatak, enclavado en el valle Tierra Mayor, sera nuestro lugar de almuerzo, mientras preparan el almuerzo tendremos tiempo de realizar una caminata por los alrededores y visitar un criadero de perros huskies.', 5, '2025-11-20 20:09:44.759', '2025-11-20 20:09:44.759');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qra001b779x7fu3shn0', 'cmi7v7qr1000o779x7ojiybld', '15:45 PM', 'Regreso al Hotel', 'Emprendemos el regreso luego de una intensa jornada!!!', 6, '2025-11-20 20:09:44.759', '2025-11-20 20:09:44.759');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qrt001z779xypnxyk6f', 'cmi7v7qrj001f779xymugxx46', '9:00 AM', 'Salida desde el Hotel', 'Salida desde el hotel en minibús rumbo al Parque Nacional Tierra del Fuego.', 0, '2025-11-20 20:09:44.777', '2025-11-20 20:09:44.777');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qrt0020779xawkhi4ql', 'cmi7v7qrj001f779xymugxx46', '9:30 AM', 'Ensenada Zaratiegui', 'Disfrutamos de hermosas vistas del Canal Beagle, con las islas Redonda, Hoste y Navarino como protagonistas.', 1, '2025-11-20 20:09:44.777', '2025-11-20 20:09:44.777');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qrt0021779x78m8cm2y', 'cmi7v7qrj001f779xymugxx46', '10:00 AM', 'Trekking por la Senda Costera', 'Emprendemos una caminata de 7 km por la Senda Costera, conociendo la flora y avifauna del Canal Beagle, el bosque fueguino y vestigios de antiguos asentamientos Yámanas.', 2, '2025-11-20 20:09:44.777', '2025-11-20 20:09:44.777');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qrt0022779xoxxwgijm', 'cmi7v7qrj001f779xymugxx46', '1:00 PM', 'Almuerzo en el Lago Roca', 'Luego de unas 3 horas de caminata, accedemos al Lago Roca y disfrutamos de un reparador almuerzo caliente.', 3, '2025-11-20 20:09:44.777', '2025-11-20 20:09:44.777');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qrt0023779x935qfr5l', 'cmi7v7qrj001f779xymugxx46', '3:00 PM', 'Botes inflables en el río Lapataia', 'Comenzamos el paseo en botes inflables por el río Lapataia, que nos lleva hasta la bahía Lapataia en el Canal Beagle, donde culmina la Ruta Panamericana y la Ruta Nacional Nº 3.', 4, '2025-11-20 20:09:44.777', '2025-11-20 20:09:44.777');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qrt0024779xig31hq82', 'cmi7v7qrj001f779xymugxx46', '5:00 PM', 'Regreso a Ushuaia', 'Desde bahía Lapataia emprendemos el regreso a Ushuaia en minibús.', 5, '2025-11-20 20:09:44.777', '2025-11-20 20:09:44.777');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qs6002n779xm5idxo4g', 'cmi7v7qrz0028779xgxp0iyhm', '8:30 AM', 'Salida desde el Hotel', 'Salida desde el hotel en minibús rumbo al Parque Nacional Tierra del Fuego.', 0, '2025-11-20 20:09:44.79', '2025-11-20 20:09:44.79');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qs6002o779x8gp73357', 'cmi7v7qrz0028779xgxp0iyhm', '9:00 AM', 'Ensenada Zaratiegui', 'Primera parada en Ensenada Zaratiegui para disfrutar de las vistas del Canal Beagle y las islas Redonda, Hoste y Navarino.', 1, '2025-11-20 20:09:44.79', '2025-11-20 20:09:44.79');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qs6002p779x5zxlnf3o', 'cmi7v7qrz0028779xgxp0iyhm', '10:00 AM', 'Lago Acigami', 'Contemplamos el majestuoso paisaje caminando por las orillas del lago Acigami.', 2, '2025-11-20 20:09:44.79', '2025-11-20 20:09:44.79');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qs6002q779xikzae2qq', 'cmi7v7qrz0028779xgxp0iyhm', '11:00 AM', 'Hacia bahía Lapataia', 'Continuamos nuestro recorrido descubriendo flora y fauna a nuestro paso hasta llegar a bahía Lapataia, el fin de la Ruta 3.', 3, '2025-11-20 20:09:44.79', '2025-11-20 20:09:44.79');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qs6002r779xuk5lplg5', 'cmi7v7qrz0028779xgxp0iyhm', '12:00 PM', 'Almuerzo', 'Enclavado en un paisaje increíble, disfrutamos de un rico almuerzo a orillas del río Lapataia.', 4, '2025-11-20 20:09:44.79', '2025-11-20 20:09:44.79');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qs6002s779xlktkov5f', 'cmi7v7qrz0028779xgxp0iyhm', '1:15 PM', 'Regreso a Ushuaia', 'Comenzamos el regreso a Ushuaia en minibús.', 5, '2025-11-20 20:09:44.79', '2025-11-20 20:09:44.79');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qs6002t779x3g9kn56e', 'cmi7v7qrz0028779xgxp0iyhm', '2:00 PM', 'Llegada al Hotel', 'De nuevo en el hotel luego de una hermosa jornada en el Parque Nacional.', 6, '2025-11-20 20:09:44.79', '2025-11-20 20:09:44.79');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qsj003b779xga9hky96', 'cmi7v7qsc002x779xaknkyl88', '9:00 AM', 'Salida desde el Hotel', 'Se buscará a los pasajeros por sus hoteles o alojamientos y se los trasladará en exclusivos transfers hasta el valle de Andorra.', 0, '2025-11-20 20:09:44.803', '2025-11-20 20:09:44.803');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qsj003c779x23dkooy4', 'cmi7v7qsc002x779xaknkyl88', '9:30 AM', 'Valle de Andorra', 'Comenzamos la caminata en el valle de Andorra, cruzando antiguas turberas y adentrándonos en el bosque fueguino.', 1, '2025-11-20 20:09:44.803', '2025-11-20 20:09:44.803');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qsj003d779xdr0f1r9y', 'cmi7v7qsc002x779xaknkyl88', '1:30 PM', 'Laguna de los Témpanos', 'Vamos tomando altura hasta llegar a orillas de la Laguna de los Témpanos, donde tendremos imponentes vistas del Glaciar Vinciguerra.', 2, '2025-11-20 20:09:44.803', '2025-11-20 20:09:44.803');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qsj003e779xp5vbydcb', 'cmi7v7qsc002x779xaknkyl88', '2:30 PM', 'Almuerzo junto al glaciar', 'Luego de explorar los alrededores y tocar el hielo, disfrutaremos del box lunch en un entorno único de montaña y hielo.', 3, '2025-11-20 20:09:44.803', '2025-11-20 20:09:44.803');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qsj003f779xrd72r3v1', 'cmi7v7qsc002x779xaknkyl88', '4:00 PM', 'Regreso al Hotel', 'Emprendemos la caminata de regreso por el mismo valle y luego el traslado a los hoteles en Ushuaia.', 4, '2025-11-20 20:09:44.803', '2025-11-20 20:09:44.803');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qsu003w779xh78szrlb', 'cmi7v7qso003j779xyimkkh7z', '9:00 AM', 'Salida desde el Hotel', 'Partida desde el hotel en minibús por vía terrestre (20 kms) hasta el Refugio Nunatak, ubicado en el valle Tierra Mayor.', 0, '2025-11-20 20:09:44.814', '2025-11-20 20:09:44.814');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qsu003x779xa5k2dwin', 'cmi7v7qso003j779xyimkkh7z', '10:00 AM', 'Refugio Nunatak e inicio del trekking', 'Desde el refugio Nunatak y luego de equiparnos con bastones de trekking iniciamos la caminata, atravesando turbales, arroyos y bosques de Lengas y Coihues.', 1, '2025-11-20 20:09:44.814', '2025-11-20 20:09:44.814');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qsu003y779xln2cdpjo', 'cmi7v7qso003j779xyimkkh7z', '12:30 PM', 'Laguna Esmeralda', 'Arribamos a la Laguna Esmeralda, en el corazón de la Reserva Natural y Paisajística Tierra del Fuego. Tiempo para descansar en sus orillas y almorzar.', 2, '2025-11-20 20:09:44.814', '2025-11-20 20:09:44.814');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qsu003z779xeo59hzko', 'cmi7v7qso003j779xyimkkh7z', '2:00 PM', 'Regreso al Refugio', 'Emprendemos el regreso al refugio por un camino diferente al de ida, disfrutando nuevas vistas del entorno.', 3, '2025-11-20 20:09:44.814', '2025-11-20 20:09:44.814');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qsu0040779xbwfhox5m', 'cmi7v7qso003j779xyimkkh7z', '3:30 PM', 'Regreso al Hotel', 'Traslado en minibús de regreso a los hoteles en Ushuaia.', 4, '2025-11-20 20:09:44.814', '2025-11-20 20:09:44.814');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qt4004m779x5jbds844', 'cmi7v7qsz0044779xkpty0z58', '08:00 AM / 14:00 PM', 'Embarque en Ushuaia', 'Embarque en el muelle turístico de Ushuaia en los horarios AM o PM para iniciar la navegación por el Canal Beagle.', 0, '2025-11-20 20:09:44.825', '2025-11-20 20:09:44.825');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qt4004n779x700jryad', 'cmi7v7qsz0044779xkpty0z58', '', 'Isla de los Pájaros', 'Navegamos hacia la Isla de los Pájaros, donde observamos diferentes aves marinas típicas del Canal Beagle.', 1, '2025-11-20 20:09:44.825', '2025-11-20 20:09:44.825');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qt4004o779xugl9rvv6', 'cmi7v7qsz0044779xkpty0z58', '', 'Isla de los Lobos', 'Continuamos hacia la Isla de los Lobos, hogar de colonias de lobos marinos, que podremos observar en su hábitat natural.', 2, '2025-11-20 20:09:44.825', '2025-11-20 20:09:44.825');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qt4004p779xz0nrnwol', 'cmi7v7qsz0044779xkpty0z58', '', 'Faro Les Eclaireurs', 'Pasamos frente al famoso Faro Les Eclaireurs, uno de los íconos del Canal Beagle, rodeado por cormoranes imperiales y otras aves.', 3, '2025-11-20 20:09:44.825', '2025-11-20 20:09:44.825');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qt4004q779x61q94q37', 'cmi7v7qsz0044779xkpty0z58', '', 'Isla Martillo – Pingüinera', 'Llegamos a Isla Martillo, donde encontramos una colonia de pingüinos magallánicos y una pequeña colonia de pingüinos papúa, avistándolos desde la embarcación.', 4, '2025-11-20 20:09:44.825', '2025-11-20 20:09:44.825');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qt4004r779xuo0lli2d', 'cmi7v7qsz0044779xkpty0z58', '14:30 PM / 20:30 PM', 'Regreso a Ushuaia', 'Regresamos a Ushuaia disfrutando de vistas panorámicas de la ciudad y la cordillera que la rodea.', 5, '2025-11-20 20:09:44.825', '2025-11-20 20:09:44.825');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtc0058779xme71mdlp', 'cmi7v7qt8004v779x2e4zdlnj', '9:00 AM', 'Salida desde el hotel', 'Salida desde los hoteles de Ushuaia en bus, tomando la Ruta Nacional N°3 en dirección al Parque Nacional Tierra del Fuego.', 0, '2025-11-20 20:09:44.833', '2025-11-20 20:09:44.833');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtc0059779xst6nmxrc', 'cmi7v7qt8004v779x2e4zdlnj', '9:30 AM', 'Valle del río Pipo y Monte Susana', 'Recorremos el valle del río Pipo y el faldeo del Monte Susana hasta llegar a la estación del Ferrocarril Austral Fueguino.', 1, '2025-11-20 20:09:44.833', '2025-11-20 20:09:44.833');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtc005a779x3mfzynl9', 'cmi7v7qt8004v779x2e4zdlnj', '10:00 AM', 'Estación Tren del Fin del Mundo', 'Visita a las instalaciones del Tren del Fin del Mundo. Quienes lo deseen pueden tomar el tren opcional, mientras el resto del grupo continúa en bus junto al guía hacia el parque.', 2, '2025-11-20 20:09:44.833', '2025-11-20 20:09:44.833');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtc005b779xci1nfrod', 'cmi7v7qt8004v779x2e4zdlnj', '11:30 AM', 'Ingreso al Parque Nacional', 'Reencuentro con el grupo dentro del Parque Nacional y recorrido por distintos miradores y puntos panorámicos.', 3, '2025-11-20 20:09:44.833', '2025-11-20 20:09:44.833');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtc005c779x1gahth7s', 'cmi7v7qt8004v779x2e4zdlnj', '12:30 PM', 'Lago Roca / Lago Acigami', 'Visita al Lago Roca (Acigami), compartido con Chile, con tiempo para cortas caminatas y fotografías del entorno montañoso.', 4, '2025-11-20 20:09:44.833', '2025-11-20 20:09:44.833');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtc005d779x2enz1yov', 'cmi7v7qt8004v779x2e4zdlnj', '1:30 PM', 'Bahía Lapataia', 'Llegada a bahía Lapataia, el final de la Ruta Nacional N°3 y de la Ruta Panamericana. Tiempo libre para caminar, sacar fotos y disfrutar del paisaje.', 5, '2025-11-20 20:09:44.833', '2025-11-20 20:09:44.833');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtc005e779x47fabhqp', 'cmi7v7qt8004v779x2e4zdlnj', '3:00 PM', 'Regreso a Ushuaia', 'Regreso en bus a los hoteles de Ushuaia luego de una jornada descubriendo el Parque Nacional del Fin del Mundo.', 6, '2025-11-20 20:09:44.833', '2025-11-20 20:09:44.833');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtm0061779x3yhg0dp8', 'cmi7v7qtj005m779xfrxge096', '8:30 AM / 3:30 PM', 'Embarque en el puerto de Ushuaia', 'Embarque en el muelle turístico de Ushuaia y salida por la Bahía Ushuaia con vistas panorámicas de la ciudad, el antiguo presidio, el Museo del Fin del Mundo y los montes Olivia y Cinco Hermanos.', 0, '2025-11-20 20:09:44.843', '2025-11-20 20:09:44.843');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtm0062779xwrtr17nu', 'cmi7v7qtj005m779xfrxge096', '', 'Navegación por el Canal Beagle', 'Ingreso al Canal Beagle rumbo a las islas Bridges, con avistaje de cormoranes imperiales, lobos marinos y diversas aves marinas típicas de la región.', 1, '2025-11-20 20:09:44.843', '2025-11-20 20:09:44.843');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtm0063779x0e4e79dy', 'cmi7v7qtj005m779xfrxge096', '', 'Desembarco en isla (según clima)', 'Si las condiciones climáticas lo permiten, desembarco en la Isla Mary Ann para una sencilla caminata, observación de flora local y vistas panorámicas de Ushuaia y la cordillera.', 2, '2025-11-20 20:09:44.843', '2025-11-20 20:09:44.843');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtm0064779x76czhab4', 'cmi7v7qtj005m779xfrxge096', '', 'Faro Les Eclaireurs', 'Continuamos navegando hacia el archipiélago Les Eclaireurs para conocer el faro homónimo, símbolo de la Ciudad del Fin del Mundo, y observar colonias de aves y restos del naufragio del Monte Cervantes.', 3, '2025-11-20 20:09:44.843', '2025-11-20 20:09:44.843');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtm0065779xogf2adzf', 'cmi7v7qtj005m779xfrxge096', '12:30 PM / 6:30 PM', 'Regreso a Ushuaia', 'Regreso aproximándonos a la costa norte del Canal Beagle, pasando frente a Estancia Túnel, la Reserva Natural y Cultural Playa Larga y el sector este de la ciudad, para finalmente arribar al puerto de Ushuaia.', 4, '2025-11-20 20:09:44.843', '2025-11-20 20:09:44.843');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtv0072779xgwndjq1p', 'cmi7v7qts006d779xmyi5pbzs', '8:30 AM', 'Traslado a Husky Park', 'Búsqueda por los hoteles y alojamientos y traslado en transfers exclusivos hasta Nunatak, en el valle Tierra Mayor.', 0, '2025-11-20 20:09:44.852', '2025-11-20 20:09:44.852');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtv0073779xqyomeylw', 'cmi7v7qts006d779xmyi5pbzs', '9:30 AM', 'Bienvenida al Husky Park', 'Recepción por parte de los guías e introducción al parque y a las actividades del día.', 1, '2025-11-20 20:09:44.852', '2025-11-20 20:09:44.852');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtv0074779xsm1vgd49', 'cmi7v7qts006d779xmyi5pbzs', '10:00 AM', 'Caminata con raquetas de nieve', 'Caminata con raquetas por el valle y el bosque fueguino, accediendo a miradores con vistas de la cordillera.', 2, '2025-11-20 20:09:44.852', '2025-11-20 20:09:44.852');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtv0075779xkdu76oeu', 'cmi7v7qts006d779xmyi5pbzs', '12:00 PM', 'Trineos deslizadores', 'Momento de pura diversión en las pendientes con trineos deslizadores, para grandes y chicos.', 3, '2025-11-20 20:09:44.852', '2025-11-20 20:09:44.852');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtv0076779xv5bsfx8o', 'cmi7v7qts006d779xmyi5pbzs', '12:30 PM', 'Almuerzo en el Domo La Base', 'Pausa para almorzar en el domo calefaccionado, antes de continuar con las actividades de la tarde.', 4, '2025-11-20 20:09:44.852', '2025-11-20 20:09:44.852');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtv0077779x23ez17cc', 'cmi7v7qts006d779xmyi5pbzs', '13:30 PM', 'Trineo Huskies, Orugas 4x4 y Motos de nieve', 'En grupos, se realizan las tres experiencias: moto de nieve, vehículo oruga y trineo tirado por huskies.', 5, '2025-11-20 20:09:44.852', '2025-11-20 20:09:44.852');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtv0078779xd39zd5q2', 'cmi7v7qts006d779xmyi5pbzs', '16:00 PM', 'Momento Husky', 'Encuentro con los huskies para interactuar, sacar fotos y disfrutar con los perros del parque.', 6, '2025-11-20 20:09:44.852', '2025-11-20 20:09:44.852');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qtv0079779x5wav3cg9', 'cmi7v7qts006d779xmyi5pbzs', '16:30 PM', 'Regreso al hotel', 'Traslado de regreso a los hoteles y alojamientos luego de un día completo de aventura en la nieve.', 7, '2025-11-20 20:09:44.852', '2025-11-20 20:09:44.852');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qu1007s779xvufgec04', 'cmi7v7qty007d779xtfylma6z', '8:30 AM', 'Traslado a Husky Park', 'Búsqueda por los hoteles o alojamientos y traslado en transfers hasta Husky Park en el valle Tierra Mayor, donde comenzará la aventura.', 0, '2025-11-20 20:09:44.857', '2025-11-20 20:09:44.857');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qu1007t779x50xzvv1i', 'cmi7v7qty007d779xtfylma6z', '9:30 AM', 'Visita guiada e instrucción', 'Bienvenida de nuestro Musher instructor, charla introductoria al mundo de los perros de trineo, visita al criadero y explicación de armado y manejo del trineo.', 1, '2025-11-20 20:09:44.857', '2025-11-20 20:09:44.857');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qu1007u779xbrjyvbva', 'cmi7v7qty007d779xtfylma6z', '11:00 AM', 'Recorrido en trineo (7 km)', 'Colocamos los arneses a los perros, los enganchamos al trineo y comenzamos el recorrido de 7 km. La caravana se adentra en el valle nevado hasta llegar al refugio del hachero.', 2, '2025-11-20 20:09:44.857', '2025-11-20 20:09:44.857');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qu1007v779xjvluseck', 'cmi7v7qty007d779xtfylma6z', '12:30 PM', 'Refrigerio en el Domo La Base', 'Reponemos calorías con un chocolate caliente con torta de manzana en un ambiente cálido y confortable.', 3, '2025-11-20 20:09:44.857', '2025-11-20 20:09:44.857');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qu1007w779x1mzyt20w', 'cmi7v7qty007d779xtfylma6z', '1:00 PM', 'Abrazo Husky', 'El momento más esperado: interacción con los perros, fotos y tiempo para disfrutar con los huskies.', 4, '2025-11-20 20:09:44.857', '2025-11-20 20:09:44.857');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qu1007x779xsk2jneix', 'cmi7v7qty007d779xtfylma6z', '1:30 PM', 'Regreso al hotel', 'Regreso desde Tierra Mayor a los hoteles, dando por finalizada la aventura.', 5, '2025-11-20 20:09:44.857', '2025-11-20 20:09:44.857');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qu8008s779xvcu5ir3r', 'cmi7v7qu40082779x7zrqdv7k', '6:30 PM', 'Traslado a Nunatak / Husky Park', 'Te buscamos por tu hotel o alojamiento y te trasladamos en nuestros transfers hasta Husky Park, en el valle Tierra Mayor, donde comienza la aventura.', 0, '2025-11-20 20:09:44.865', '2025-11-20 20:09:44.865');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qu8008t779xuxq1qom4', 'cmi7v7qu40082779x7zrqdv7k', '7:30 PM', 'Inicio de actividades en la nieve', 'El guía da la bienvenida en el Domo La Base y organiza el orden de las actividades: trineo de huskies, moto de nieve y caminata con raquetas.', 1, '2025-11-20 20:09:44.865', '2025-11-20 20:09:44.865');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qu8008u779xuaz66pdl', 'cmi7v7qu40082779x7zrqdv7k', '9:00 PM', 'Cena en fogón', 'Caminamos hasta el tepee guiados por farolitos. Disfrutás de brochettes, guiso al fuego, vinos, vino caliente y el tradicional café del hachero, con guitarreada.', 2, '2025-11-20 20:09:44.865', '2025-11-20 20:09:44.865');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qu8008v779x34qluk3o', 'cmi7v7qu40082779x7zrqdv7k', '11:00 PM', 'Regreso al hotel', 'Finalizada la cena, emprendemos el regreso a tu hotel luego de una noche única entre nieve y fuego.', 3, '2025-11-20 20:09:44.865', '2025-11-20 20:09:44.865');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7que009f779xrxfmrme2', 'cmi7v7qub0090779xnh2b7cwg', '8:30 AM', 'Salida desde el hotel', 'Partida desde tu hotel por la ruta nacional N° 3 rumbo a los lagos Escondido y Fagnano.', 0, '2025-11-20 20:09:44.871', '2025-11-20 20:09:44.871');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7que009g779xfryodjlj', 'cmi7v7qub0090779xnh2b7cwg', '10:30 AM', 'Lago Fagnano y Paso Garibaldi', 'Cruzamos la cordillera fueguina por el Paso Garibaldi y accedemos al Lago Fagnano por una vieja huella de hacheros, recorriendo la costa con paradas panorámicas.', 1, '2025-11-20 20:09:44.871', '2025-11-20 20:09:44.871');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7que009h779xsurc3twl', 'cmi7v7qub0090779xnh2b7cwg', '12:30 PM', 'Almuerzo en refugio Nunatak', 'Almuerzo con asado en el refugio Nunatak. Mientras se prepara, podés caminar por los alrededores o disfrutar de las pistas de trineos deslizadores (opcional).', 2, '2025-11-20 20:09:44.871', '2025-11-20 20:09:44.871');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7que009i779xt4nvbxv9', 'cmi7v7qub0090779xnh2b7cwg', '2:30 PM', 'Actividades opcionales', 'Tiempo libre para contratar actividades opcionales como moto de nieve y trineos tirados por huskies, sujeto a disponibilidad.', 3, '2025-11-20 20:09:44.871', '2025-11-20 20:09:44.871');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7que009j779xsckce8wg', 'cmi7v7qub0090779xnh2b7cwg', '4:00 PM', 'Regreso al hotel', 'Emprendemos el regreso a Ushuaia luego de una jornada completa de aventura 4x4.', 4, '2025-11-20 20:09:44.871', '2025-11-20 20:09:44.871');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7quk00a1779xdt5zmhok', 'cmi7v7qui009n779xd6gp30uu', '8:30 AM', 'Salida desde el hotel', 'Partida desde el hotel en minibús por vía terrestre (20 km) hasta el valle Tierra Mayor.', 0, '2025-11-20 20:09:44.877', '2025-11-20 20:09:44.877');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7quk00a2779x5hf0dpvq', 'cmi7v7qui009n779xd6gp30uu', '10:00 AM', 'Inicio del trekking', 'Desde el refugio Nunatak, luego de equiparnos con crampones o raquetas de nieve y bastón de trekking, iniciamos la caminata atravesando valles nevados, arroyos congelados y bosques de lengas y coihues.', 1, '2025-11-20 20:09:44.877', '2025-11-20 20:09:44.877');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7quk00a3779xmu6bxc0t', 'cmi7v7qui009n779xd6gp30uu', '1:30 PM', 'Llegada a Laguna Esmeralda', 'Llegamos a la Laguna Esmeralda, enclavada en la Reserva Natural y Paisajística Tierra del Fuego. Tiempo para descansar en sus orillas y disfrutar del box lunch.', 2, '2025-11-20 20:09:44.877', '2025-11-20 20:09:44.877');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7quk00a4779x9mxckefs', 'cmi7v7qui009n779xd6gp30uu', '', 'Regreso al refugio y al hotel', 'Emprendemos el regreso al refugio por un camino diferente al de ida y posteriormente retornamos al hotel.', 3, '2025-11-20 20:09:44.877', '2025-11-20 20:09:44.877');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7quq00ap779xho8v4to9', 'cmi7v7qun00a8779xdxem53dt', '8:30 AM', 'Traslado a Husky Park Ushuaia', 'Te buscamos por tu hotel o alojamiento y te trasladamos en nuestros transfers hasta Husky Park, en el valle Tierra Mayor.', 0, '2025-11-20 20:09:44.883', '2025-11-20 20:09:44.883');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7quq00aq779xus91mswv', 'cmi7v7qun00a8779xdxem53dt', '9:00 AM', 'Visita guiada al parque', 'Recorrido por el parque para conocer la historia, el cuidado y el entrenamiento de los perros, la muestra de exploradores y la vida en la nieve.', 1, '2025-11-20 20:09:44.883', '2025-11-20 20:09:44.883');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7quq00ar779xn8v8ps4g', 'cmi7v7qun00a8779xdxem53dt', '10:00 AM', 'Paseo en trineo Husky', 'Iniciamos la travesía en trineos tirados por huskies, atravesando el valle y el bosque por antiguos caminos de leñadores hasta la gran planicie nevada.', 2, '2025-11-20 20:09:44.883', '2025-11-20 20:09:44.883');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7quq00as779x06rjg05q', 'cmi7v7qun00a8779xdxem53dt', '11:00 AM', 'Paseo en moto de nieve', 'Tras la instrucción del guía, nos equipamos con cascos y realizamos un recorrido de aproximadamente 5 km en moto de nieve entre bosques y planicies.', 3, '2025-11-20 20:09:44.883', '2025-11-20 20:09:44.883');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7quq00at779x229ei66g', 'cmi7v7qun00a8779xdxem53dt', '12:00 PM', 'Abrazo Husky y chocolate caliente', 'Tiempo para abrazar y sacarse fotos con los huskies, y luego recuperar calorías con un chocolate caliente en el refugio.', 4, '2025-11-20 20:09:44.883', '2025-11-20 20:09:44.883');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7quq00au779xyecgcvqc', 'cmi7v7qun00a8779xdxem53dt', '1:30 PM', 'Regreso al hotel', 'Emprendemos el regreso a Ushuaia después de una mañana completa de aventura en la nieve.', 5, '2025-11-20 20:09:44.883', '2025-11-20 20:09:44.883');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qux00bf779x9dhq65v5', 'cmi7v7qut00ay779xdbrgrq44', '8:30 AM', 'Traslado a Husky Park', 'Te buscamos por tu hotel o alojamiento y te trasladamos en nuestros transfers hasta Husky Park Ushuaia, en el valle Tierra Mayor, donde comienza la aventura.', 0, '2025-11-20 20:09:44.889', '2025-11-20 20:09:44.889');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qux00bg779xqmwyngza', 'cmi7v7qut00ay779xdbrgrq44', '9:00 AM', 'Visita al Husky Park', 'Recorrido guiado por el parque: monumento a los exploradores, historias de las travesías polares, visita a los huskies y a la muestra de exploradores antárticos.', 1, '2025-11-20 20:09:44.889', '2025-11-20 20:09:44.889');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qux00bh779xxdeg58df', 'cmi7v7qut00ay779xdbrgrq44', '10:00 AM', 'Travesía en vehículos a oruga (4 km)', 'Avanzamos en columna de dos vehículos a oruga, recreando técnicas de detección y cruce de grietas hasta llegar al Módulo Antártico.', 2, '2025-11-20 20:09:44.889', '2025-11-20 20:09:44.889');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qux00bi779x1e6lb928', 'cmi7v7qut00ay779xdbrgrq44', '11:00 AM', 'Módulo Antártico', 'Experiencia inmersiva que combina elementos sensoriales, visuales y narrativos. Disfrutás de bebida caliente y galletas antárticas antes de continuar la travesía.', 3, '2025-11-20 20:09:44.889', '2025-11-20 20:09:44.889');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qux00bj779x26xyu7eh', 'cmi7v7qut00ay779xdbrgrq44', '12:00 PM', 'Travesía en motos de nieve (6 km)', 'El guía brinda las instrucciones de manejo y salimos en patrulla en motos de nieve, completando un recorrido de 6 km hasta regresar a Husky Park.', 4, '2025-11-20 20:09:44.889', '2025-11-20 20:09:44.889');
INSERT INTO public."TourTimelineItem" VALUES ('cmi7v7qux00bk779x2kqpb5g0', 'cmi7v7qut00ay779xdbrgrq44', '1:30 PM', 'Regreso al hotel', 'Finalizada la experiencia, emprendemos el regreso a tu hotel luego de un verdadero desafío polar.', 5, '2025-11-20 20:09:44.889', '2025-11-20 20:09:44.889');
